import {feedMeshes} from './feed-meshes.js';

// Support hardware is deliberately independent of dish seam hardware.
export const FEED={rodDiameter:6.35,socketBore:6.7,pivotHeight:22,topRadius:65,eyeToMouth:44,engagement:22,minEngagement:18,maxEngagement:26,pinBore:5.4};
const FEED_TAU=2*Math.PI;
const fz=(r,p)=>r*r/(4*p.diameter*p.fd);
const fhole=(r,a=0,w=4.6)=>({r0:r-w/2,r1:r+w/2,a0:a-w/(2*r),a1:a+w/(2*r),r,a,w,shape:'round'});
export function feedDatum(p){const r=p.diameter/2-34;return{r,front:fz(r+25,p)+3,rear:fz(r-25,p)-Math.max(8,p.thickness+4),holes:[fhole(r-14),fhole(r+14)]};}
export function feedFits(p,n,rows){if(!p.feedMode)return true;if(n%p.feedLegs)return false;const d=feedDatum(p),r0=45+(rows-1)*(p.diameter/2-45)/rows;return d.r-31>Math.max(78,r0+10)&&d.r*Math.sin(Math.PI/n)>42;}
export function addFeedPad(spec,p){
 const d=feedDatum(p),oldBack=spec.backFn,oldLevels=[...spec.levels];
 const weight=(x,y)=>{const q=Math.max(Math.abs(Math.hypot(x,y)-d.r)-25,Math.abs(y)-20,0),t=Math.min(1,q/6);return 1-t*t*(3-2*t);};
 const delta=(x,y)=>Math.max(0,oldBack(x,y)-d.rear)*weight(x,y);
 spec.backFn=(x,y)=>oldBack(x,y)-delta(x,y);
 // Move all internal levels together toward the back; preserve their order and the RF face.
 spec.levels=oldLevels.map((fn,i)=>i===oldLevels.length-1?fn:(x,y)=>fn(x,y)-delta(x,y));
 spec.feedHoles=d.holes;spec.feedDatum=d;
 spec.layers=spec.layers.map(layer=>({...layer,holes:[...(layer.holes||[]),...d.holes]}));
 spec.gridBoxes.push(...d.holes,...[20,25,31].map(t=>({r0:d.r-t,r1:d.r+t,a0:-t/d.r,a1:t/d.r})));
 spec.extraR=[...(spec.extraR||[]),d.r-25,d.r,d.r+25];return spec;
}
export function cassegrainGeometry(p){
 const f=p.diameter*p.fd,g=p.backFocus,zv=f*p.secondaryPosition,zc=(f+g)/2,c=(f-g)/2,a=zv-zc,b2=c*c-a*a;
 if(!(g<0&&a>0&&a<c&&b2>0))throw Error('Cassegrain needs a rear focus below the vertex and a secondary vertex between the two-focus midpoint and the primary focus.');
 const surface=r=>zc+a*Math.sqrt(1+r*r/b2),R=p.diameter/2,depth=fz(R,p);
 let lo=0,hi=R;for(let i=0;i<70;i++){const r=(lo+hi)/2;if(surface(r)<f+(depth-f)*r/R)lo=r;else hi=r;}
 const intercept=(lo+hi)/2,radius=intercept*1.04,edgeZ=surface(radius),backZ=edgeZ+10;
 if(radius<35)throw Error('The secondary is too small for the 56 mm mounting pattern. Move its vertex closer to the dish (lower vertex / focus ratio), or enlarge the dish.');
 if(radius>43)throw Error('This secondary is too large for the standard carrier clearance (86 mm maximum). Move its vertex closer to the primary focus, or use a separately engineered carrier.');
 // Conservative central passage check: returned rim ray at the highest point of the central hub.
 const passageZ=fz(60,p),returnRadius=intercept*(passageZ-g)/(surface(intercept)-g);
 if(returnRadius>13.5)throw Error('The returned Cassegrain ray bundle does not clear the 30 mm hub opening with 1.5 mm radial margin. Move the rear focus closer to the vertex or redesign the hub.');
 return{primaryFocus:f,backFocus:g,vertex:zv,center:zc,c,a,b2,interceptRadius:intercept,radius,edgeZ,backZ,returnRadius,surface};
}
export function feedGeometry(p,layout){
 if(!p.feedMode)return null;const d=feedDatum(p),secondary=p.feedMode===2?cassegrainGeometry(p):null;
 const carrierFace=secondary?secondary.backZ:p.diameter*p.fd-p.phaseOffset,upperZ=carrierFace-FEED.pivotHeight,lowerZ=d.front+FEED.pivotHeight;
 const distance=Math.hypot(d.r-FEED.topRadius,upperZ-lowerZ),cut=distance-2*FEED.eyeToMouth+2*FEED.engagement;
 if(upperZ-lowerZ<25)throw Error('The carrier is too low for the rod fittings. Reduce the phase-center offset, increase f/D, or use a custom support.');
 if(distance<100)throw Error('The support span is too short for the two 44 mm rod-end fittings. Increase dish size/focal ratio or use a custom compact support.');
 if(cut>450)throw Error('The required 1/4-inch rods exceed the 450 mm prototype limit. Use larger tubes and a separately engineered support.');
 const phase=p.staggerRings?((layout.rows-1)%2)*Math.PI/layout.n:0,legs=Array.from({length:p.feedLegs},(_,i)=>{const angle=phase+i*FEED_TAU/p.feedLegs;return{number:i+1,angle,lower:[d.r*Math.cos(angle),d.r*Math.sin(angle),lowerZ],upper:[FEED.topRadius*Math.cos(angle),FEED.topRadius*Math.sin(angle),upperZ],pivotDistance:distance,cutLength:cut};});
 const warnings=['Support rods and the carrier scatter/block RF; no gain or wind rating is implied.','The rod-end pivots are locked after alignment. Do not leave a freely hinged structure.'];
 if(p.feedLegs===4)warnings.push('Four legs are redundantly constrained: leave the fourth loose until the carrier is aligned, then set its length without preload.');
 if(secondary){warnings.push('Cassegrain is an experimental geometric-optics layout, not an RF-qualified antenna. A band-specific rear feed and electromagnetic validation are still required.');if(!p.frequencyGHz)warnings.push('Operating frequency is unspecified: secondary electrical size cannot be assessed.');else if(secondary.radius*2/(299.792458/p.frequencyGHz)<5)warnings.push('Secondary diameter is less than five wavelengths: diffraction is significant; ray geometry alone cannot establish performance.');}
 return{mode:p.feedMode===1?'prime-focus':'cassegrain',legs,datum:d,carrierFace,upperZ,lowerZ,cutLength:cut,pivotDistance:distance,rodAngle:Math.atan2(upperZ-lowerZ,d.r-FEED.topRadius)*180/Math.PI,phase,secondary,warnings};
}
const transform=(mesh,fn)=>({v:mesh.v.map(fn),f:mesh.f});
const at=(mesh,xyz)=>transform(mesh,v=>v.map((x,k)=>x+xyz[k]));
const rz=(mesh,a)=>transform(mesh,([x,y,z])=>[Math.cos(a)*x-Math.sin(a)*y,Math.sin(a)*x+Math.cos(a)*y,z]);
const flip=mesh=>transform(mesh,([x,y,z])=>[x,-y,-z]);
function rodEndAt(A,B){const dx=B[0]-A[0],dz=B[2]-A[2],L=Math.hypot(dx,dz),u=dx/L,w=dz/L;return transform(feedMeshes['rod-end'],([x,y,z])=>[A[0]+w*x+u*z,A[1]+y,A[2]-u*x+w*z]);}
export function appendFeedParts(m,api){
 if(!m.p.feedMode)return;const {patch,printMesh,bounds}=api,p=m.p,g=feedGeometry(p,m.layout),d=g.datum;m.feed=g;
 const add=(id,name,mesh,qty,angles=[0],printing=null)=>{const pm=printing||printMesh(mesh),dim=bounds(pm).size;if(dim[0]>p.bedX-2*p.margin||dim[1]>p.bedY-2*p.margin||dim[2]>p.bedZ-2)throw Error(name+' does not fit the usable print volume.');const part={id,name,mesh,print:pm,output:pm,supportMeshes:[],dim,qty,kind:'feed',row:-1,angle:0,bedRotation:0,spec:{holes:[]}};m.parts.push(part);for(const a of angles)m.instances.push({part,a});return part;};
 const angles=g.legs.map(x=>x.angle),holes=d.holes,box={r0:d.r-24,r1:d.r+24,a0:-20/d.r,a1:20/d.r,holes};
 add('feed-saddle','Feed · curved front saddle',patch({...box,topFn:()=>d.front,backFn:(x,y)=>fz(Math.hypot(x,y),p)+.08},p),p.feedLegs,angles);
 // Print the curved saddle on its flat top, exposing the curved mating face upward.
 const saddle=m.parts.at(-1);saddle.print=printMesh(flip(saddle.mesh));saddle.output=saddle.print;saddle.dim=bounds(saddle.print).size;
 add('feed-backer','Feed · rear load spreader',patch({...box,topFn:()=>d.rear,backFn:()=>d.rear-4},p),p.feedLegs,angles);
 const clevisPrint=printMesh(feedMeshes.clevis);
 add('feed-lower-clevis','Feed · lower locking clevis',at(feedMeshes.clevis,[d.r,0,d.front]),p.feedLegs,angles,clevisPrint);
 add('feed-upper-clevis','Feed · upper locking clevis',at(flip(feedMeshes.clevis),[FEED.topRadius,0,g.carrierFace]),p.feedLegs,angles,clevisPrint);
 const low=[d.r,0,g.lowerZ],high=[FEED.topRadius,0,g.upperZ],rodPrint=printMesh(transform(feedMeshes['rod-end'],([x,y,z])=>[x,z,-y]));
 add('feed-lower-rod-end','Feed · lower rod clamp',rodEndAt(low,high),p.feedLegs,angles,rodPrint);
 add('feed-upper-rod-end','Feed · upper rod clamp',rodEndAt(high,low),p.feedLegs,angles,rodPrint);
 add('feed-carrier','Feed · open carrier / 56 mm BCD',at(rz(feedMeshes['carrier-'+p.feedLegs],g.phase),[0,0,g.carrierFace]),1,[0],printMesh(feedMeshes['carrier-'+p.feedLegs]));
 if(g.secondary){const s=g.secondary,holes=Array.from({length:4},(_,i)=>fhole(28,g.phase+Math.PI/4+i*Math.PI/2,5.6));const spec={r0:0,r1:s.radius,a0:0,a1:FEED_TAU,levels:[(x,y)=>s.surface(Math.hypot(x,y)),()=>s.backZ-7,()=>s.backZ],layers:[{},{holes}],gridBoxes:holes,holes};const mesh=patch(spec,p);add('secondary-reflector','Secondary · hyperbolic blank',mesh,1,[0],printMesh(flip(mesh)));}
}
export function feedManifest(m){if(!m.feed)return{enabled:false};const g=m.feed,s=g.secondary;return{enabled:true,revision:1,mode:g.mode,legs:m.p.feedLegs,rod_diameter_mm:6.35,stock:'smooth solid 1/4-inch metal rod; not threaded rod',cut_length_mm:g.cutLength,pivot_distance_mm:g.pivotDistance,nominal_engagement_each_end_mm:22,engagement_range_mm:[18,26],carrier_lower_face_z_mm:g.carrierFace,phase_center_offset_from_carrier_lower_face_mm:m.p.feedMode===1?m.p.phaseOffset:null,carrier_opening_mm:40,carrier_adapter_bolt_circle_mm:56,carrier_adapter_bolts:'4 × M4 at 45, 135, 225, 315 degrees plus outer-ring phase',legs_geometry:g.legs,secondary:s?{primary_focus_z:s.primaryFocus,rear_focus_z:s.backFocus,vertex_z:s.vertex,hyperbola_center_z:s.center,a:s.a,b:Math.sqrt(s.b2),diameter_mm:2*s.radius,geometric_rim_intercept_radius_mm:s.interceptRadius,front_surface:'z = center + a * sqrt(1 + r^2 / b^2)',back_plane_z:s.backZ,conservative_return_bundle_radius_mm:s.returnRadius}:null,hardware:feedHardware(m),warnings:g.warnings};}
export function rodCSV(m){if(!m.feed)return'';return 'leg,stock,diameter_mm,pivot_distance_mm,eye_to_mouth_each_mm,engagement_each_mm,cut_length_mm,cut_length_inches,azimuth_degrees,lower_pivot_z_mm,upper_pivot_z_mm\n'+m.feed.legs.map(l=>[l.number,'smooth metal rod',6.35,l.pivotDistance.toFixed(3),44,22,l.cutLength.toFixed(3),(l.cutLength/25.4).toFixed(4),(l.angle*180/Math.PI).toFixed(3),l.lower[2].toFixed(3),l.upper[2].toFixed(3)].join(',')).join('\n')+'\n';}
export function feedHardware(m){if(!m.feed)return [];const n=m.p.feedLegs,d=m.feed.datum,grip=d.front-d.rear+10,minimum=grip+2+3.2+1.4+.4,length=[16,20,25,30,35,40,45,50,55,60,65,70,80,90,100].find(x=>x>=minimum);if(!length)throw Error('Lower support-foot stack needs a separately sourced screw length.');return [
 {item:'lower-foot screw',spec:`M4 × ${length}`,quantity:2*n,grip_mm:grip,note:'Two 1 mm washers, 3.2 mm nut, minimum two threads beyond nut; verify actual stack'},
 {item:'upper-foot screw',spec:'M4 × 20',quantity:2*n,note:'Two 1 mm washers and plain M4 nut'},
 {item:'rod-clamp screw',spec:'M4 × 16',quantity:2*n,note:'Plain M4 nut in 7.5 mm AF pocket; no washer allowance'},
 {item:'pivot screw',spec:'M5 × 30',quantity:2*n,note:'Two 1 mm washers and M5 prevailing-torque nut; lock pivot after alignment'},
 {item:'M4 nut',spec:'M4 / 7 mm AF / 3.2 mm tall',quantity:6*n,note:'Foot and rod-clamp positions'},
 {item:'M4 washer',spec:'1 mm thick',quantity:8*n,note:'Both sides of each foot fastener'},
 {item:'M5 nut',spec:'prevailing-torque / verify actual height',quantity:2*n,note:'Pivot locking'},
 {item:'M5 washer',spec:'1 mm thick',quantity:4*n,note:'Both sides of each pivot'},
 ...(m.feed.secondary?[{item:'secondary screw',spec:'M4 × 12',quantity:4,note:'6 mm carrier, no washer, nominal 6 mm entry into 7 mm blind cavity; verify tip clearance'}, {item:'secondary insert',spec:'short M4 / maximum 6 mm length / compatible with 5.6 mm pilot',quantity:4,note:'Install 0.5 mm below flat back; not the 8.1 mm dish insert'}]:[])
 ];}
export function feedHardwareCSV(m){const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';return 'item,specification,quantity,grip_mm,note\n'+feedHardware(m).map(x=>[x.item,x.spec,x.quantity,x.grip_mm?.toFixed(3),x.note].map(quote).join(',')).join('\n')+'\n';}
export function feedGuide(m){if(!m.feed)return'';const g=m.feed,lower=feedHardware(m)[0];return `# PETAL rod support · ${g.mode}\n\nExperimental accessory revision 1. Regenerate the mount petals and all feed-support parts together. The seam/hub interface remains revision 9. If the chosen rod count changes the petal/ring segmentation, regenerate the entire dish including its hub and plates. Four rods cannot be added at equal petal-center spacing to the default six-petal dish. Rods and fasteners are purchased, not printed.\n\n## Layout and rod cuts\n\n${m.p.feedLegs} equally spaced supports. The generator selects a petal count divisible by ${m.p.feedLegs}; only the named mount petals receive reinforced pads and two extra through holes. Install them at the azimuths in RODS.csv. These local accessory holes remain through holes even when the dish seam hardware uses blind inserts. Mount feet cover them.\n\nUse smooth 6.35 mm (1/4 inch) metal rod, preferably aluminum for the initial lightweight indoor article. This fitting is NOT for 1/4-20 threaded rod. Deburr the ends. Cut ${m.p.feedLegs} rods nominally ${g.cutLength.toFixed(2)} mm (${(g.cutLength/25.4).toFixed(4)} inch). Cut slightly long for trial assembly and trim to the measured fit; do not force an oversize rod between locked pivots.\n\nPivot-center span = ${g.pivotDistance.toFixed(2)} mm. Each printed rod end places its mouth 44 mm from the pin center. Cut = span − 2×44 + 2×22. Mark 22 mm nominal insertion at each end; retain 18–26 mm engagement and at least 2 mm bottom clearance. The ±4 mm per-end range is assembly adjustment, not a substitute for recalculating a different feed. The lower/upper pivots are at z=${g.lowerZ.toFixed(2)} / ${g.upperZ.toFixed(2)} mm, measured from the extrapolated dish vertex.\n\n## Hardware and assembly\n\nPer leg: two smooth-rod split clamps; two M5×30 pivot screws, four M5 washers and two M5 prevailing-torque nuts; two M4×16 clamp screws and two M4 nuts (7 mm AF); two M4×20 upper-foot screws, washers and nuts. Lower-foot screws: ${2*m.p.feedLegs} × ${lower.spec}, nominal grip ${lower.grip_mm.toFixed(2)} mm plus two 1 mm washers, nut and protruding threads. The flat upper/lower datums make the total grip equal at the two positions even though the saddle and petal thicknesses vary. Verify actual printed stacks before buying the set. FEED-HARDWARE.csv lists support hardware separately from the dish hardware. No printed threads. Start with fit checks of the 6.7 mm socket, 5.4 mm pivot bore and nut pocket.\n\nRear backer → reinforced petal → curved saddle → clevis. Keep the saddle face clean of foil/glue. Use the paired screws, not a single bolt through an unsupported shell. Place the carrier with the 40 mm center opening above the dish; its clevises face downward. The four M4 holes on a 56 mm bolt circle are an adapter interface, not a universal feed standard. Design a short feed-specific adapter once its dimensions and phase center are known.\n\nKeep pivot pins and rod clamps loose during alignment. Set carrier center, height and tilt with an independent jig, then tighten progressively. Lock the pivot faces after alignment: these are positioning hinges, not free-running ball joints. With four legs, fit the fourth last at zero preload. Never use the fourth rod to bend the petals into place. Recheck shape after every tightening step and after changing elevation. Strain-relieve coax along one rod with an axis service loop.\n\n## Optical meaning\n\n${g.secondary?`The secondary is a convex hyperboloid facing the primary dish. Primary focus z=${m.focal.toFixed(2)} mm; rear feed phase center z=${g.secondary.backFocus.toFixed(2)} mm; secondary vertex z=${g.secondary.vertex.toFixed(2)} mm. Its diameter is ${(2*g.secondary.radius).toFixed(2)} mm, including a 4% radial geometric margin beyond the intercepted primary-rim ray. This is NOT an optimized edge taper. The secondary rear plane contacts the carrier lower face at z=${g.carrierFace.toFixed(2)} mm. Coat the curved face toward the main dish; leave the flat mounting back uncoated. Four blind Ø5.6×7 mm cavities accept a separately verified short M4 heat-set insert no longer than 6 mm. Recess the insert 0.5 mm below the flat back. Use M4×12 screws through the 6 mm carrier without washers, with actual thread engagement checked; tips must never reach the curved face. The feed behind the main dish must point toward the secondary. Its physical aperture, beam taper, phase center, polarization, and clearance through the 30 mm hub are not determined by a ray model. No rear-feed adapter is supplied.`:`Place the feed PHASE CENTER at z=${m.focal.toFixed(2)} mm, not its mouth or mounting flange. Carrier lower face z=${g.carrierFace.toFixed(2)} mm; entered phase offset ${m.p.phaseOffset.toFixed(2)} mm is signed from that lower face along +z (away from the primary). Thus phase center = carrier face + offset. A zero offset is only a datum placeholder until the actual feed is specified. The feed points toward the main dish.`}\n\n${g.warnings.map(w=>'- '+w).join('\n')}\n\nThe long rods are not printable parts and are shown only as reference lines in the viewer. Print clevises base-down and carriers flat; rod clamps are exported on their side so the eye-to-socket load path lies mainly in the layer plane. Inspect/support the horizontal rod bore and split-clamp roofs in the slicer. Print the saddle on its flat face; the secondary is back-down, with slicer support under the central blind-hole roofs if needed. Verify the reflective surface after support removal.\n\nTest one leg before a full set: fit, clamp slip, pin locking, creep and repeated assembly. Then verify carrier movement under light lateral/axial load at several dish elevations. No supported payload, wind speed, or continuous-service temperature is assigned.\n`;}
